export function mergeContent(base,stored){if(Array.isArray(base))return Array.isArray(stored)?stored:structuredClone(base);if(base&&typeof base==='object'){const out={};for(const key of Object.keys(base))out[key]=mergeContent(base[key],stored?.[key]);return out;}return stored===undefined?base:stored;}
export function extendValidation(raw,out,defaults,fail){
 const str=(s,max=4000)=>{if(typeof s!=='string'||s.length>max)fail('Check the text format or length.');return s.trim();};
 const url=s=>{s=str(s,1000);if(!s)return s;try{const u=new URL(s);if(u.protocol==='https:'&&!u.username&&!u.password)return s;}catch{}fail('Links must use a full HTTPS URL.');};
 const img=s=>/^\/(photos|media)\/[\w./-]+$/.test(s)?s:url(s);
 out.settings={};for(const[key,value]of Object.entries(defaults.settings)){out.settings[key]=typeof value==='boolean'?raw.settings[key]===true:key==='bannerImage'?img(raw.settings[key]):['instagram','facebook','linkedin','tiktok','youtube','otherSocialUrl'].includes(key)?url(raw.settings[key]):str(raw.settings[key],2000);}
 if(!out.settings.customerButton||!out.settings.candidateButton)fail('Both journey buttons need a label.');
 const code=out.settings.whatsappCountryCode,num=out.settings.whatsappNumber;if(code&&!/^\d{1,4}$/.test(code))fail('WhatsApp country code must contain digits only, without +.');if(num&&!/^\d{4,14}$/.test(num))fail('WhatsApp number must contain digits only, without spaces.');if(code&&num&&(!/^[1-9]\d{6,14}$/.test(code+num)))fail('Check the complete international WhatsApp number.');
 out.terms=str(raw.terms,12000);out.policySeo={};for(const key of Object.keys(defaults.policySeo))out.policySeo[key]=str(raw.policySeo[key],500);
 out.copy={};for(const key of Object.keys(defaults.copy))out.copy[key]=str(raw.copy[key]);
 const schemas={jobs:{id:'',title:'',location:'',type:'',requirements:'',closing:'',status:'Draft'},projects:{id:'',title:'',location:'',description:'',image:'',imageAlt:'',status:'Draft'},testimonials:{id:'',client:'',role:'',quote:'',status:'Draft'},certifications:{id:'',title:'',issuer:'',description:'',url:'',image:'',imageAlt:'',status:'Draft'},announcements:{id:'',title:'',text:'',url:'',status:'Draft'}};
 for(const[name,schema]of Object.entries(schemas)){if(!Array.isArray(raw[name])||raw[name].length>50)fail('Use up to 50 entries per collection.');const ids=new Set();out[name]=raw[name].map(item=>{const row={};for(const key of Object.keys(schema))row[key]=key==='image'?img(item[key]):key==='url'?url(item[key]):str(item[key]);if(!/^[\w-]{1,80}$/.test(row.id)||ids.has(row.id))fail('Each entry needs a unique ID.');ids.add(row.id);if(!['Draft','Published','Closed'].includes(row.status))fail('Select Draft, Published or Closed.');if(row.closing&&!/^\d{4}-\d{2}-\d{2}$/.test(row.closing))fail('Use YYYY-MM-DD for a closing date.');if(row.status==='Published'&&!(name==='testimonials'?row.client&&row.quote:row.title&&(name==='jobs'?row.location&&row.requirements:name==='projects'?row.location&&row.description:true)))fail('Complete the entry before publishing it.');return row;});}
 out.forms={};for(const kind of ['inquiry','application']){const f=raw.forms[kind],base=defaults.forms[kind];out.forms[kind]={};const target=out.forms[kind];for(const key of ['heading','intro','submit','confirmation','consent']){target[key]=str(f[key]);if(!target[key])fail('Each form needs a heading, button, confirmation and consent wording.');}target.fields={};for(const key of Object.keys(base.fields)){const field=f.fields[key];if(!field)fail('Missing form field settings.');const core=['name','phone','email'].includes(key);target.fields[key]={label:str(field.label,200),required:core||field.required===true,enabled:core||field.enabled===true};if(!target.fields[key].label)fail('Each field needs a label.');}if(!Array.isArray(f.extras)||f.extras.length>12)fail('Use up to 12 extra fields per form.');const ids=new Set();target.extras=f.extras.map(x=>{const item={id:str(x.id,80),label:str(x.label,200),type:str(x.type,30),required:x.required===true,enabled:x.enabled===true};if(!/^[a-z0-9-]+$/.test(item.id)||ids.has(item.id)||!item.label||!['text','textarea','date','number'].includes(item.type))fail('Check the extra field ID, label and type.');ids.add(item.id);return item;});}
 return out;
}
export function published(rows){return rows.filter(x=>x.status==='Published');}
